CREATE TABLE IF NOT EXISTS ib_offices (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_name VARCHAR(150) NOT NULL, address TEXT, phone VARCHAR(50), manager VARCHAR(100), status VARCHAR(20) NOT NULL DEFAULT 'active', created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, name VARCHAR(100) NOT NULL, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'Support User', status VARCHAR(20) NOT NULL DEFAULT 'active', created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_customers (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, customer_id VARCHAR(50) NOT NULL, pppoe_username VARCHAR(100), pppoe_password VARCHAR(100), customer_name VARCHAR(150) NOT NULL, mobile VARCHAR(30), address TEXT, area VARCHAR(100), package_id BIGINT NOT NULL DEFAULT 0, monthly_bill NUMERIC(12,2) NOT NULL DEFAULT 0, previous_due NUMERIC(12,2) NOT NULL DEFAULT 0, connection_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'active', created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS ib_customers_office ON ib_customers(office_id);
CREATE INDEX IF NOT EXISTS ib_customers_code ON ib_customers(customer_id);
CREATE TABLE IF NOT EXISTS ib_packages (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, package_name VARCHAR(100) NOT NULL, speed VARCHAR(50), price NUMERIC(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_bill_batches (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL, bill_month CHAR(7) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'processed', processed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reversed_at TIMESTAMP, UNIQUE(office_id,bill_month)
);
CREATE TABLE IF NOT EXISTS ib_bill_lines (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, batch_id BIGINT NOT NULL REFERENCES ib_bill_batches(id), customer_db_id BIGINT NOT NULL DEFAULT 0, customer_id VARCHAR(50) NOT NULL, customer_name VARCHAR(150) NOT NULL, mobile VARCHAR(30), area VARCHAR(100), monthly_bill NUMERIC(12,2) NOT NULL DEFAULT 0, previous_due NUMERIC(12,2) NOT NULL DEFAULT 0, total_due NUMERIC(12,2) NOT NULL DEFAULT 0, paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0, balance_due NUMERIC(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'due'
);
CREATE INDEX IF NOT EXISTS ib_bill_lines_batch ON ib_bill_lines(batch_id);
CREATE TABLE IF NOT EXISTS ib_payments (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, batch_id BIGINT NOT NULL DEFAULT 0, bill_line_id BIGINT NOT NULL DEFAULT 0, customer_db_id BIGINT NOT NULL DEFAULT 0, customer_id VARCHAR(50) NOT NULL, customer_name VARCHAR(150) NOT NULL, bill_month CHAR(7) NOT NULL, payment_date DATE NOT NULL, amount NUMERIC(12,2) NOT NULL DEFAULT 0, payment_method VARCHAR(30) NOT NULL DEFAULT 'Cash', reference VARCHAR(100), note TEXT, receipt_no VARCHAR(50), created_by BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS ib_payments_office_month ON ib_payments(office_id,bill_month);
CREATE INDEX IF NOT EXISTS ib_payments_line ON ib_payments(bill_line_id);
CREATE TABLE IF NOT EXISTS ib_isp_payments (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, invoice_no VARCHAR(50) UNIQUE, payment_date DATE NOT NULL, provider VARCHAR(150) NOT NULL, bill_month VARCHAR(20) NOT NULL, amount NUMERIC(12,2) NOT NULL DEFAULT 0, note TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_office_expenses (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, expense_date DATE NOT NULL, expense_type VARCHAR(100) NOT NULL, amount NUMERIC(12,2) NOT NULL DEFAULT 0, note TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_staff_salary (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, office_id BIGINT NOT NULL DEFAULT 0, staff_name VARCHAR(100) NOT NULL, salary_month CHAR(7) NOT NULL, total_salary NUMERIC(12,2) NOT NULL DEFAULT 0, payment_date DATE, note TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_line_transfer (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_db_id BIGINT NOT NULL, customer_id VARCHAR(50) NOT NULL, old_package VARCHAR(100), new_package VARCHAR(100), transfer_date DATE, type VARCHAR(30), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_new_line (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_db_id BIGINT DEFAULT 0, customer_id VARCHAR(50) NOT NULL, customer_name VARCHAR(150) NOT NULL, package_id BIGINT DEFAULT 0, monthly_bill NUMERIC(12,2) DEFAULT 0, entry_date DATE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ib_settings (key VARCHAR(100) PRIMARY KEY, value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS ib_sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES ib_users(id) ON DELETE CASCADE, expires_at TIMESTAMP NOT NULL);
